import { ChevronLeft, ChevronRight, Compass, Maximize, Minimize, Pause, Play, RotateCcw } from 'lucide-react';
import { useCallback, useMemo, useRef, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { useMuseumConfig } from '../../config/ConfigProvider';
import { resolveAssetUrl } from '../../config/loadConfig';
import type { SiteModelConfig } from '../../config/schema';
import { useFullscreen } from '../../shared/fullscreen';
import { hasWebGLSupport } from '../../shared/webgl';
import { SiteScene, type SiteMarkerConfig, type SiteSceneComponent, type SiteViewState } from './SiteScene';
import './site.css';

export interface SitePageProps {
  SceneComponent?: SiteSceneComponent;
  supportsWebGL?: () => boolean;
}

/*
 * 这里原先还有一个 `basemap` 透传（precision 的场地页传根地图瓦片 → SiteScene 做地理配准 +
 * 铺影像地面）。现场看过之后：压在场地模型下面的那块影像地面是**斜的**（模型按自己的轴向，
 * 影像是按正北配准的，两者差一个航向角），一圈卫星图因此像一块歪着垫在模型下的板子。
 * 现在 /site 不铺地面 —— 模型直接落在纸色背景上，与站里其它页面同一套语言。
 * 影像地面的能力本身没删：`/roam?roam=plane` 的连续漫游仍然在用它（RoamPage 传 basemap），
 * 那里的影像不是"垫在模型下的板子"，而是漫游这件事本身。
 */

/**
 * 设备卡片列表（没有场地模型、或没有 WebGL 时用它当入口）。
 * 底部设备栏删掉之后，这是"点不进三维"时的唯一入口——每一张卡片直接进设备页。
 */
function DeviceList({ onOpen }: { onOpen(deviceId: string): void }) {
  const { config } = useMuseumConfig();
  return (
    <div className="site-index-list">
      {config.devices.map(device => (
        <button type="button" key={device.id} className="site-index-card" onClick={() => onOpen(device.id)}>
          <img src={resolveAssetUrl(device.poster)} alt="" loading="lazy" decoding="async" />
          <span>
            <strong>{device.name}</strong>
          </span>
          <ChevronRight aria-hidden="true" />
        </button>
      ))}
      {config.devices.length === 0 && <p className="site-empty">配置里还没有设备。</p>}
    </div>
  );
}

function DeviceIndex({ site, onOpen }: { site: SiteModelConfig | undefined; onOpen(deviceId: string): void }) {
  return (
    <section className="site-explorer">
      <header className="feature-hero compact">
        <span>EQUIPMENT</span>
        <h1>{site?.name ?? '设备模型'}</h1>
        <p>{site?.summary || '选择一台设备查看三维模型。'}</p>
      </header>
      <DeviceList onOpen={onOpen} />
    </section>
  );
}

/** 有场地但没有 WebGL：静态海报 + 设备卡片列表（不能只留一张海报——那样就再也进不去设备了）。 */
function SiteStaticFallback({ site, onOpen }: { site: SiteModelConfig; onOpen(deviceId: string): void }) {
  return (
    <section className="site-explorer">
      <header className="feature-hero compact">
        <span>EQUIPMENT</span>
        <h1>{site.name}</h1>
        <p>{site.summary || '选择一台设备查看三维模型。'}</p>
      </header>
      <div className="site-webgl-fallback is-static">
        <img src={resolveAssetUrl(site.poster)} alt={`${site.name}静态预览`} />
        <strong>三维查看暂不可用</strong>
      </div>
      <DeviceList onOpen={onOpen} />
    </section>
  );
}

export function SitePage({ SceneComponent = SiteScene, supportsWebGL = hasWebGLSupport }: SitePageProps) {
  const navigate = useNavigate();
  const location = useLocation();
  const { config } = useMuseumConfig();
  const site = config.siteModel;
  const [webglAvailable] = useState(() => supportsWebGL());
  const [view, setView] = useState<SiteViewState>({ reset: 0, rotate: false, top: false });
  const [issues, setIssues] = useState(0);
  // 「全屏查看」按钮的宿主元素：全屏状态与能力都挂在它身上（见 `useFullscreen`）。
  const studioRef = useRef<HTMLDivElement>(null);
  const fullscreen = useFullscreen(studioRef);

  const markers = useMemo<SiteMarkerConfig[]>(() => (site?.hotspots ?? []).map(hotspot => {
    const device = config.devices.find(item => item.id === hotspot.deviceId);
    return {
      id: hotspot.id,
      label: hotspot.label || device?.name || hotspot.deviceId,
      // 标记只显示设备名：副标题来自配置，实测手机上两行标签把画面压得很乱，
      // 而且内容通常与设备名重复（"库外试验场内的工频试验成套装置"）。
      description: hotspot.description ?? '',
    };
  }), [site, config.devices]);

  const activate = useCallback((hotspotId: string) => {
    const hotspot = site?.hotspots.find(item => item.id === hotspotId);
    if (hotspot) navigate(`/devices/${hotspot.deviceId}`);
  }, [navigate, site]);

  /* 「返回上一次」：展馆的网页端/平板端常常没有浏览器返回键（平板还是全屏 kiosk），
     所以这一页必须自带返回入口。有来路就退回上一页，没有来路（直接输入网址/刷新进来的
     `location.key === 'default'`）就回设备模型——那是这里被删掉的那条信息条当年的去处。 */
  const goBack = useCallback(() => {
    if (location.key === 'default') navigate('/devices');
    else navigate(-1);
  }, [location.key, navigate]);

  if (!site) return <DeviceIndex site={site} onOpen={id => navigate(`/devices/${id}`)} />;
  if (!webglAvailable) return <SiteStaticFallback site={site} onOpen={id => navigate(`/devices/${id}`)} />;

  return (
    <section className="site-explorer has-stage">
      <div ref={studioRef} className="site-studio">
        <SceneComponent
          site={site}
          markers={markers}
          view={view}
          onActivate={activate}
          onIssues={setIssues}
        />
        {/* 遮罩层已按现场要求去掉：`site-vignette`（四角压暗）与 `site-haze`（顶部柔光衬底）
            都是压在三维画面上的一层"滤镜"，现场希望画面就是画面本身。 */}

        {/*
          头部一行：左边身份（场域名），右边工具圆钮，与设备模型页、地图页同一结构：
          标题行固定行高（--page-head-title-line），右上角工具与它共用一条中线；
          其它信息一律绝对定位在下方，不参与居中计算。
          眉标"场地模型"已去掉：底部导航已经写着栏目名，这一行不必再重复一次。
        */}
        <div className="site-header">
          {/* 返回放在最左、与右上角工具同样的圆钮（同一行中线）：这是全页唯一的"出去"入口，
              尺寸按触摸目标给足 44px，免得眼神先去找浏览器返回键。 */}
          <button type="button" className="site-back" aria-label="返回上一次" title="返回上一次" onClick={goBack}>
            <ChevronLeft aria-hidden="true" />
          </button>

          <header className="site-identity">
            {/* 场域名回到这里：precision 外侧那条 52px 信息条已经删掉（返回键与导航重复、
                页名又占了整个画面上沿），这一行恢复成"左边身份、右边工具"的老结构。
               它是整页唯一的 <h1>，所以由 precision 的皮肤层给它纸张底+细线，压在任何视角上都读得清。 */}
            <h1>{site.name}</h1>
            {/* 这里只留"这是哪、叫什么"。场地简介、三角面数、操作说明都去过：
                模型信息属于内部资料，不该占手机首屏。 */}
            {issues > 0 && <small className="site-issue">{issues} 个设备锚点未在场地模型中找到，标记位置可能不准</small>}
          </header>

          <nav className="site-tools" aria-label="场地视角">
            <button
              type="button"
              aria-label={view.rotate ? '暂停自动旋转' : '自动旋转'}
              aria-pressed={view.rotate}
              className={view.rotate ? 'is-active' : ''}
              onClick={() => setView(current => ({ ...current, rotate: !current.rotate }))}
            >
              {view.rotate ? <Pause /> : <Play />}
            </button>
            <button
              type="button"
              aria-label={view.top ? '回到默认视角' : '俯视全场'}
              aria-pressed={view.top}
              className={view.top ? 'is-active' : ''}
              onClick={() => setView(current => ({ ...current, top: !current.top }))}
            >
              <Compass />
            </button>
            <button type="button" aria-label="复位视角" onClick={() => setView(current => ({ ...current, reset: current.reset + 1, top: false }))}><RotateCcw /></button>
            {/* 全屏按钮：状态与能力都由 `useFullscreen` 管（再点一次是退出，不是空操作）。 */}
            {fullscreen.supported && <button type="button" aria-label={fullscreen.active ? '退出全屏' : '全屏查看'} aria-pressed={fullscreen.active} onClick={fullscreen.toggle}>{fullscreen.active ? <Minimize /> : <Maximize />}</button>}
          </nav>
        </div>

        {/*
          底部设备栏（`.site-device-rail`）已按现场要求整条去掉（方案 ②，对照图见 docs/design-preview/site-rail-*.png）：
          手机上一屏只有两台设备，却要占 74px 高 + 102px 离屏底，还得横滑——右边那张卡永远被切掉半个，
          而且一张卡里塞了"进设备 / 在场地里定位"两个不同动作，容易误触。
          现在**设备入口就是场地上的标记**（点标记直接进设备页），画面净高多出 82px。
          代价与补偿：少了缩略图预览，所以标记本身放大了（见 `site.css` 的 `.site-marker-pin` / `.site-marker-label`）；
          "在场地里定位"这个动作一并删掉，转视角用右上角的"复位视角/俯视全场"就够了。
        */}

        {/* 页脚只在"有设备没在场地里标点"时才出现——那是数据问题，必须说；
            "N 台设备可查看"这类计数属于旁白，已按现场要求去掉。 */}
        {config.devices.length > markers.length && (
          <footer className="site-footer">
            <span>另有 {config.devices.length - markers.length} 台设备未在场地中标点</span>
          </footer>
        )}
      </div>
    </section>
  );
}

export default SitePage;
